import {SqliteAgentActionJournal,SqliteAgentActionRecoveryDiscovery,AgentActionRecoveryCoordinator,AgentActionRecoveryWorker,createActionHttpsVerifier} from '../../dist/index.js';
const [path,url]=process.argv.slice(2),scope={tenantId:'tenant',agentId:'agent'},actor={tenantId:'tenant',principalId:'operator'},discovery=new SqliteAgentActionRecoveryDiscovery(path,{scope,authorize:()=>true}),errors=[];
let journal;
try{
 const verify=createActionHttpsVerifier({scope,runId:'run',operationId:'operation',url,bearerToken:'a'.repeat(32),timeoutMs:5000,maxPending:1,interpret:(body,context)=>{if(!body||body.state!=='applied'||body.key!==context.idempotencyKey||!body.result)throw Error('Unverified provider evidence');return {outcome:'applied',result:body.result};}});
 const coordinator=new AgentActionRecoveryCoordinator({scope,actor,discovery,maxRunsPerPass:5,pollMs:100,authorize:()=>true,open:candidate=>{const selected=new SqliteAgentActionJournal(path,{scope,runId:candidate.runId,leaseToken:'retired-token',clock:()=>110});return {worker:new AgentActionRecoveryWorker({journal:selected,maxPerPass:5,pollMs:100,authorize:()=>true,evidence:()=>({principalId:'operator',reference:'provider-case'}),verify,onError:error=>errors.push(error.message)}),close:()=>selected.close()};},onError:error=>errors.push(error.message)});
 const count=await coordinator.runOnce();await coordinator.stop();journal=new SqliteAgentActionJournal(path,{scope,runId:'run',leaseToken:'retired-token',clock:()=>110});process.send({count,status:journal.get('call').status,errors,evidence:journal.listReconciliations()});
}catch(error){process.send({error:String(error)});}finally{discovery.close();journal?.close();}
